    def __init__(self, expr: str):
        self.expr = expr
        self.pos = 0

    def parse(self) -> float:
        self.skip_whitespace()
        result = self.parse_expression()
        self.skip_whitespace()
        if self.pos < len(self.expr):
            raise SyntaxError("Unexpected characters at the end of expression.")
        return result

    def parse_expression(self) -> float:
        term = self.parse_term()
        while self.pos < len(self.expr):
            self.skip_whitespace()
            if self.pos < len(self.expr) and self.expr[self.pos] in ('+', '-'):
                op = self.expr[self.pos]
                self.pos += 1
                self.skip_whitespace()
                term2 = self.parse_term()
                term = term + term2 if op == '+' else term - term2
            else:
                break
        return term

    def parse_term(self) -> float:
        factor = self.parse_factor()
        while self.pos < len(self.expr):
            self.skip_whitespace()
            if self.pos < len(self.expr) and self.expr[self.pos] in ('*', '/'):
                op = self.expr[self.pos]
                self.pos += 1
                self.skip_whitespace()
                factor2 = self.parse_factor()
                factor = factor * factor2 if op == '*' else factor / factor2
            else:
                break
        return factor

    def parse_factor(self) -> float:
        self.skip_whitespace()
        if self.pos < len(self.expr):
            if self.expr[self.pos] == '(':
                self.pos += 1
                result = self.parse_expression()
                self.skip_whitespace()
                if self.pos < len(self.expr) and self.expr[self.pos] == ')':
                    self.pos += 1
                    return result
                else:
                    raise SyntaxError("Missing closing parenthesis.")
