                       (self.expr[self.pos].isdigit() or self.expr[self.pos] == '.')):
                    self.pos += 1
                return float(self.expr[start:self.pos])
            else:
                raise SyntaxError("Unexpected character: {}".format(self.expr[self.pos]))

    def skip_whitespace(self):
        while self.pos < len(self.expr) and self.expr[self.pos].isspace():
            self.pos += 1

