class ArithmeticEvaluator:
    def __init__(self, expression: str):
        self.expression = expression.replace(' ', '')
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def error(self):
        raise Exception("Invalid character in the expression.")

    def advance(self):
        self.position += 1
        if self.position < len(self.expression):
            self.current_char = self.expression[self.position]
        else:
            self.current_char = None

    def parse_number(self):
        number_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            number_str += self.current_char
            self.advance()
        return float(number_str)

    def parse_parentheses(self):
        self.advance()  # Skip the opening parenthesis
        result = self.parse_expression()
        self.advance()  # Skip the closing parenthesis
        return result

    def parse_factor(self):
        if self.current_char.isdigit() or self.current_char == '.':
            return self.parse_number()
        elif self.current_char == '(':
            return self.parse_parentheses()
        self.error()

    def parse_term(self):
        result = self.parse_factor()
        while self.current_char in ('*', '/'):
            operator = self.current_char
            self.advance()
            if operator == '*':
                result *= self.parse_factor()
            elif operator == '/':
                divisor = self.parse_factor()
                if divisor == 0:
                    raise ZeroDivisionError("Division by zero.")
                result /= divisor
        return result

    def parse_expression(self):
        result = self.parse_term()
        while self.current_char in ('+', '-'):
            operator = self.current_char
            self.advance()
            if operator == '+':
                result += self.parse_term()
            elif operator == '-':
                result -= self.parse_term()
        return result

def evaluate(expr: str) -> float:
    """
    Evaluates a given arithmetic expression using a recursive descent parser technique.
    """
    evaluator = ArithmeticEvaluator(expr)
    return evaluator.parse_expression()
